-- ============================================================================
-- Engagement-safe reflection accounting.
--
-- Goal: make sure a reflection row that was generated by the notification
-- pipeline but never engaged with by the user (ignored push) can NEVER be
-- mistakenly counted in any metric — including future queries that forget to
-- apply the client-side `isCompletedPause` / `isFullRitualPause` filters in
-- src/lib/engaged-pause.ts.
--
-- This migration adds:
--   1) reflections.source — explicit provenance tag.
--   2) v_reflections_completed — filtered view (outcome set).
--   3) v_reflections_engaged  — filtered view (full flow).
--   4) v_notification_response_rate — per-day analytics for admin dashboards.
--   5) Admin SELECT policy on pause_notifications.
--   6) purge_orphan_notification_reflections() — TTL cleanup for orphan rows.
--
-- None of the existing data / ingestion paths change meaning; the default
-- `source = 'manual'` preserves behaviour for every legacy row.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1) Explicit provenance column on reflections.
-- ---------------------------------------------------------------------------
-- Values in use:
--   'manual'         — user-initiated pause (client insert via use-holzen.ts).
--   'cron_volatility'— auto-generated by check-volatility cron.
-- Extend later as needed (e.g. 'cron_night', 'admin_seed'). Kept as text so
-- new sources don't require an enum migration.
ALTER TABLE public.reflections
  ADD COLUMN IF NOT EXISTS source text DEFAULT 'manual';

-- Backfill: anything pre-dating this migration is a user-initiated pause
-- (cron-originated rows were only introduced after this flag existed).
UPDATE public.reflections
SET source = 'manual'
WHERE source IS NULL;

-- Supports the purge predicate below without scanning the whole table.
-- Partial index: only indexes the orphan shape we care about, staying tiny.
CREATE INDEX IF NOT EXISTS idx_reflections_orphan_notifications
  ON public.reflections (created_at)
  WHERE source IS NOT NULL
    AND source <> 'manual'
    AND outcome IS NULL
    AND mood_after IS NULL
    AND breathing_completed = false;

-- ---------------------------------------------------------------------------
-- 2) v_reflections_completed — canonical "a decision was recorded" view.
-- Any server-side report that queries this view can't forget the filter.
-- ---------------------------------------------------------------------------
DROP VIEW IF EXISTS public.v_reflections_completed;
CREATE VIEW public.v_reflections_completed AS
SELECT *
FROM public.reflections r
WHERE r.outcome IS NOT NULL
  AND r.outcome <> '';

ALTER VIEW public.v_reflections_completed SET (security_invoker = true);

-- ---------------------------------------------------------------------------
-- 3) v_reflections_engaged — full ritual: breathing + mood + mood_after + outcome.
-- Matches isFullRitualPause() in src/lib/engaged-pause.ts.
-- ---------------------------------------------------------------------------
DROP VIEW IF EXISTS public.v_reflections_engaged;
CREATE VIEW public.v_reflections_engaged AS
SELECT *
FROM public.reflections r
WHERE r.breathing_completed = true
  AND r.mood IS NOT NULL AND r.mood <> ''
  AND r.mood_after IS NOT NULL AND r.mood_after <> ''
  AND r.outcome IS NOT NULL AND r.outcome <> '';

ALTER VIEW public.v_reflections_engaged SET (security_invoker = true);

-- ---------------------------------------------------------------------------
-- 4) Admin SELECT on pause_notifications (mirrors the admin_reflections_policy
--    so the response-rate view below is visible in the admin dashboard).
-- ---------------------------------------------------------------------------
DROP POLICY IF EXISTS "Admins can view all pause notifications" ON public.pause_notifications;
CREATE POLICY "Admins can view all pause notifications"
  ON public.pause_notifications
  FOR SELECT
  USING (public.is_admin());

-- ---------------------------------------------------------------------------
-- 5) v_notification_response_rate — daily analytic, explicitly separated
--    from behavioural scores. Counts every dispatched notification and
--    classifies it by what the attached reflection became.
--
-- A notification is:
--   completed → reflection has outcome set
--   engaged   → reflection also has breathing + mood + mood_after
--   ignored   → reflection_id is null OR reflection has no outcome
-- ---------------------------------------------------------------------------
DROP VIEW IF EXISTS public.v_notification_response_rate;
CREATE VIEW public.v_notification_response_rate AS
SELECT
  date_trunc('day', pn.created_at)::date AS day,
  count(*) AS notifications,
  count(*) FILTER (
    WHERE r.outcome IS NOT NULL AND r.outcome <> ''
  ) AS completed,
  count(*) FILTER (
    WHERE r.breathing_completed = true
      AND r.mood IS NOT NULL AND r.mood <> ''
      AND r.mood_after IS NOT NULL AND r.mood_after <> ''
      AND r.outcome IS NOT NULL AND r.outcome <> ''
  ) AS engaged,
  count(*) FILTER (
    WHERE pn.reflection_id IS NULL
       OR r.outcome IS NULL
       OR r.outcome = ''
  ) AS ignored,
  -- Convenience percentages (0–100, one decimal).
  round(
    100.0 * count(*) FILTER (WHERE r.outcome IS NOT NULL AND r.outcome <> '')
           / nullif(count(*), 0),
    1
  ) AS pct_completed,
  round(
    100.0 * count(*) FILTER (
      WHERE r.breathing_completed = true
        AND r.mood IS NOT NULL AND r.mood <> ''
        AND r.mood_after IS NOT NULL AND r.mood_after <> ''
        AND r.outcome IS NOT NULL AND r.outcome <> ''
    ) / nullif(count(*), 0),
    1
  ) AS pct_engaged
FROM public.pause_notifications pn
LEFT JOIN public.reflections r ON r.id = pn.reflection_id
GROUP BY 1
ORDER BY 1 DESC;

ALTER VIEW public.v_notification_response_rate SET (security_invoker = true);

-- ---------------------------------------------------------------------------
-- 6) purge_orphan_notification_reflections — TTL cleanup for orphan rows.
--
-- Deletes reflection rows that were generated by a non-manual source, never
-- engaged with by the user, and are older than the cutoff. Because
-- pause_notifications.reflection_id is ON DELETE SET NULL, the bell history
-- stays intact (the notification row remains, its reflection link nulls out).
--
-- Returns the number of rows deleted (0 on no-op). Safe to schedule via
-- pg_cron; see docs/ops/cron-setup.md.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.purge_orphan_notification_reflections(
  cutoff_days integer DEFAULT 30
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  deleted_count integer;
BEGIN
  IF cutoff_days IS NULL OR cutoff_days < 1 THEN
    RAISE EXCEPTION 'cutoff_days must be >= 1';
  END IF;

  WITH victims AS (
    DELETE FROM public.reflections
    WHERE source IS NOT NULL
      AND source <> 'manual'
      AND outcome IS NULL
      AND mood_after IS NULL
      AND (breathing_completed IS NULL OR breathing_completed = false)
      AND created_at < (now() - make_interval(days => cutoff_days))
    RETURNING 1
  )
  SELECT count(*) INTO deleted_count FROM victims;

  RETURN COALESCE(deleted_count, 0);
END;
$$;

-- Only trusted roles should run the purge. Service role (cron) is granted
-- EXECUTE; clients are not.
REVOKE ALL ON FUNCTION public.purge_orphan_notification_reflections(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.purge_orphan_notification_reflections(integer) TO service_role;
